   @Transactional
   public void publishOrdered(List<OutboxEvent> events) {
       events.stream()
             .sorted(Comparator.comparing(OutboxEvent::getTimestamp))
             .forEach(evt -> kafkaTemplate.send("domain-events", evt.getType().name(), evt.getPayload()));
   }
   ```

